#!/usr/bin/env bash

bp_add_generated() { GENERATED+=("$1"); }
bp_add_skipped() { SKIPPED+=("$1"); }
bp_join_by() { local separator="$1" item result=""; shift; for item in "$@"; do [[ -z "$result" ]] || result+="$separator"; result+="$item"; done; printf '%s' "$result"; }
bp_plan_project() { bp_add_generated '.ddev/config.yaml'; [[ "$ENABLE_PHP_SETTINGS" == y ]] && bp_add_generated '.ddev/php/99-development.ini'; [[ "$ENABLE_REDIS_SERVICE" == y ]] && bp_add_generated '.ddev/docker-compose.redis.yaml'; if [[ "$ENABLE_OTEL" == y ]]; then bp_add_generated '.ddev/docker-compose.otel.yaml'; bp_add_generated '.ddev/otel/collector-config.yaml'; fi; if [[ "$ENABLE_MAKEFILE" == y ]]; then [[ -e "$TARGET_DIR/Makefile" ]] && bp_add_skipped 'Makefile (existing)' || bp_add_generated Makefile; elif [[ -n "$MAKEFILE_SKIP_REASON" ]]; then bp_add_skipped "Makefile ............ $MAKEFILE_SKIP_REASON"; fi; if [[ "$ENABLE_EDITORCONFIG" == y ]]; then [[ -e "$TARGET_DIR/.editorconfig" ]] && bp_add_skipped '.editorconfig (existing)' || bp_add_generated .editorconfig; fi; if [[ "$ENABLE_ENV_TEMPLATE" == y ]]; then [[ -e "$TARGET_DIR/.env.local.example" ]] && bp_add_skipped '.env.local.example (existing)' || bp_add_generated .env.local.example; fi; }
bp_print_report() { if "$DRY_RUN"; then printf '\nDDEV Blueprint dry run completed\nNo files were written.\n'; else printf '\nDDEV Blueprint completed successfully\n'; fi; printf '\nProject:\n  Name ............... %s\n  Target ............. %s\n' "$PROJECT_NAME" "$TARGET_DIR"; printf '\nDDEV:\n  PHP ................ %s\n  Web server ......... %s\n  Document root ...... %s\n' "$PHP_VERSION" "$WEBSERVER" "$DOCROOT"; if [[ "$DB_TYPE" == none ]]; then printf '  Database ........... disabled\n'; else printf '  Database ........... %s %s\n' "$DB_TYPE" "$DB_VERSION"; fi; (( ${#HOSTNAMES[@]} )) && printf '  Hostnames .......... %s\n' "$(bp_join_by ', ' "${HOSTNAMES[@]}")" || true; (( ${#FQDNS[@]} )) && printf '  FQDNs .............. %s\n' "$(bp_join_by ', ' "${FQDNS[@]}")" || true; ALL_EXTENSIONS=("${EXTENSIONS[@]}" "${DB_EXTENSIONS[@]}"); (( ${#ALL_EXTENSIONS[@]} )) && printf '\nPHP extensions:\n  %s\n' "$(bp_join_by ', ' "${ALL_EXTENSIONS[@]}")" || true; if [[ "$ENABLE_MAKEFILE" == y && -e "$TARGET_DIR/Makefile" && ! "$DRY_RUN" ]]; then MAKEFILE_STATUS='skipped (existing)'; elif [[ "$ENABLE_MAKEFILE" == y ]]; then MAKEFILE_STATUS="$([[ "$DRY_RUN" == true ]] && printf 'planned (host make)' || printf 'generated (host make)')"; elif [[ -n "$MAKEFILE_SKIP_REASON" ]]; then MAKEFILE_STATUS=skipped; else MAKEFILE_STATUS=disabled; fi; if [[ "$ENABLE_EDITORCONFIG" == y && -e "$TARGET_DIR/.editorconfig" && ! "$DRY_RUN" ]]; then EDITORCONFIG_STATUS='skipped (existing)'; elif [[ "$ENABLE_EDITORCONFIG" == y ]]; then EDITORCONFIG_STATUS="$([[ "$DRY_RUN" == true ]] && printf planned || printf generated)"; else EDITORCONFIG_STATUS=disabled; fi; if [[ "$ENABLE_ENV_TEMPLATE" == y && -e "$TARGET_DIR/.env.local.example" && ! "$DRY_RUN" ]]; then ENV_STATUS='skipped (existing)'; elif [[ "$ENABLE_ENV_TEMPLATE" == y ]]; then ENV_STATUS="$([[ "$DRY_RUN" == true ]] && printf planned || printf generated)"; else ENV_STATUS=disabled; fi; printf '\nDevelopment:\n  Standard tools ..... %s\n  OPcache ............ %s\n  Xdebug ............. disabled\n  Makefile ........... %s\n  .editorconfig ...... %s\n  Env example ........ %s\n' "$([[ "$ENABLE_DEV_TOOLS" == y ]] && printf enabled || printf disabled)" "$([[ "$ENABLE_PHP_SETTINGS" == y ]] && printf enabled || printf disabled)" "$MAKEFILE_STATUS" "$EDITORCONFIG_STATUS" "$ENV_STATUS"; if [[ "$ENABLE_REDIS_SERVICE" == y || "$ENABLE_OTEL" == y ]]; then printf '\nServices:\n'; [[ "$ENABLE_REDIS_SERVICE" == y ]] && printf '  Redis .............. redis:%s\n' "$REDIS_TAG"; [[ "$ENABLE_OTEL" == y ]] && printf '  OpenTelemetry ...... enabled\n'; fi; (( ${#GENERATED[@]} )) && { printf '\nGenerated:\n'; printf '  %s\n' "${GENERATED[@]}"; } || true; (( ${#SKIPPED[@]} )) && { printf '\nSkipped:\n'; printf '  %s\n' "${SKIPPED[@]}"; } || true; printf '\nNext steps:\n  cd %s\n  ddev start\n' "$TARGET_DIR"; if [[ "$ENABLE_MAKEFILE" == y ]] && { "$DRY_RUN" || [[ ! -e "$TARGET_DIR/Makefile" ]]; }; then printf '  make composer-install\n'; fi; return 0; }
